127	async function folioMetadata() {
128	  const folios = await loadFoliosFromIdb();
129	  const metadata: FolioUsageMetadata[] = await Promise.all(
130	    folios.map(async (folio) => ({
131	      folioId: folio.id,
132	      currentWords: countDraftWords(await loadFolioContentFromIdb(folio.id)),
133	      updatedAt: folio.updatedAt,
134	    })),
135	  );
136	  return { folios, metadata };
137	}
