306	    let cancelled = false;
307	    cleanup(() => {
308	      cancelled = true;
309	    });
310	    if (loading || provider !== "convex" || !user || !client || !localLoaded) {
311	      store.remoteState =
312	        typeof navigator !== "undefined" && !navigator.onLine
