315	      store.synchronized = undefined;
316	      return;
317	    }
318	    const accountId = user.analyticsId;
319	    if (!accountId || !navigator.onLine) {
320	      store.remoteState = navigator.onLine ? "error" : "offline";
321	      return;
322	    }
323	    store.remoteState = "loading";
324	    const queriedAt = Date.now();
325	    const requested = createUsageRange(selectedPreset, queriedAt);
326	    const recent =
327	      selectedPreset === "all" ? createUsageRange("90d", queriedAt) : requested;
328	    const loadBreakdown = async (
329	      dimension: "feature" | "provider_model" | "folio",
330	    ) => {
331	      const rows: ServerBreakdownRow[] = [];
332	      let cursor: string | null = null;
333	      let isDone = false;
