335	      while (!isDone && pages < MAX_REMOTE_PAGES) {
336	        const result = (await client.query(api.usage.getMyBreakdown, {
337	          from: requested.from,
338	          to: requested.to,
339	          now: queriedAt,
340	          dimension,
341	          paginationOpts: { numItems: 100, cursor },
342	        })) as unknown as {
343	          page: ServerBreakdownRow[];
344	          isDone: boolean;
345	          continueCursor: string;
346	        };
347	        rows.push(...result.page);
348	        cursor = result.continueCursor;
349	        isDone = result.isDone;
350	        pages += 1;
351	      }
352	      return { rows, truncated: !isDone };
353	    };
354	    try {
355	      const [
356	        coverage,
357	        remoteOverall,
358	        remoteDaily,
359	        remoteWriting,
360	        feature,
361	        providerModel,
362	        folio,
363	        recentPage,
364	        pending,
365	        localActivities,
366	        localFolios,
367	      ] = await Promise.all([
