373	        }),
374	        client.query(api.usage.getMyDaily, {
375	          from: recent.from!,
376	          to: recent.to,
377	        }),
378	        client.query(api.writingActivity.getMyActivity, {
379	          from: recent.from!,
380	          to: recent.to,
381	        }),
382	        loadBreakdown("feature"),
383	        loadBreakdown("provider_model"),
384	        loadBreakdown("folio"),
385	        client.query(api.usage.listMyRecent, {
386	          paginationOpts: { numItems: 100, cursor: null },
387	        }),
388	        listPendingEvents(accountId, requested),
389	        usageLedger.listWritingActivity({
390	          from: requested.from ?? recent.from!,
391	          to: requested.to,
392	          limit: 2_000,
393	        }),
394	        folioMetadata(),
395	      ]);
396	      const boundedRecent = recentPage as unknown as {
397	        page: UsageEvent[];
398	        isDone: boolean;
399	      };
400	      if (cancelled) return;
401	      const summary = combineDeskUsage({
402	        range: requested,
403	        now: queriedAt,
404	        remoteOverall: remoteOverall as ServerUsageMetrics,
405	        remoteDaily: remoteDaily as ServerDailyUsage[],
406	        remoteBreakdowns: {
407	          feature: feature.rows,
408	          provider_model: providerModel.rows,
409	          folio: folio.rows,
410	        },
411	        remoteWriting: remoteWriting as ServerWritingActivity,
412	        recentServerEvents: boundedRecent.page,
413	        pendingEvents: pending.events,
414	        localActivities,
415	        folios: localFolios.metadata,
