518	        >
519	          <span class="mr-2 text-xs font-semibold tracking-[0.1em] uppercase text-[var(--color-ink-muted)]">
520	            Range
521	          </span>
522	          {(["7d", "30d", "90d", "all"] as UsageRangePreset[]).map((range) => (
523	            <button
