537	        </nav>
538	        {!store.loaded ? (
539	          <div class="py-20" role="status">
540	            <p class="dept-label">Reading the ledger</p>
541	            <div class="mt-4 h-px w-full animate-pulse bg-[var(--color-ink-muted)]" />
