23	function download(content: string, filename: string, mime: string): void {
24	  const href = URL.createObjectURL(new Blob([content], { type: mime }));
25	  const link = document.createElement("a");
26	  link.href = href;
27	  link.download = filename;
28	  link.click();
29	  URL.revokeObjectURL(href);
30	}
