47	/** Export, sync, and delete the content-free usage ledger. Lives in Account. */
48	export const DataControls = component$<{
49	  range: UsageRange;
50	  accountId?: string;
51	  onLocalDeleted$?: QRL<() => void>;
52	  onSynchronizedDelete$?: QRL<() => Promise<void>>;
53	}>((props) => {
54	  const message = useSignal("");
55	  const readiness = useSignal<UsageSyncReadiness>({ status: "disabled" });
56	  const confirmLocal = useSignal(false);
