16	/** Refresh while Twyne is open; server-held pending intent survives reloads. */
17	export const PublicDeskSync = component$(() => {
18	  const auth = useAuth();
19	  const convex = useConvexClient();
20	  // eslint-disable-next-line qwik/no-use-visible-task
21	  useVisibleTask$(({ track, cleanup }) => {
22	    const identity = track(() =>
23	      hasAuthenticatedConvexIdentity(auth.value) ? auth.value.user?.id : null,
24	    );
25	    const did = track(() => auth.value.atproto?.did);
26	    const client = track(() => convex.value);
27	    if (!identity || !client || !did) return;
28	    let disposed = false;
29	    let running = false;
30	    const active = () =>
31	      !disposed &&
32	      auth.value.user?.id === identity &&
33	      auth.value.atproto?.did === did;
34	    const sync = async () => {
35	      if (running || !active()) return;
36	      running = true;
37	      try {
38	        const { getAgent } = await import("../../utils/atproto");
39	        const { syncPublicDesk } = await import("../../utils/public-desk-sync");
40	        const run = async () => {
41	          if (!active()) return;
42	          await syncPublicDesk({
43	            agent: await getAgent(),
44	            prepare: async () => {
45	              const job = await client.mutation(deskPrepareRef, {});
46	              return job
47	                ? {
48	                    ...job,
49	                    record: job.recordJson ? JSON.parse(job.recordJson) : null,
50	                  }
51	                : null;
52	            },
53	            acknowledge: (revision) =>
54	              client.mutation(deskAcknowledgeRef, { revision }),
55	            active,
56	          });
57	        };
58	        // Serialize tabs sharing this OAuth session; remote CAS covers devices.
59	        if (navigator.locks)
60	          await navigator.locks.request(`twyne-public-desk:${did}`, run);
61	        else await run();
62	      } catch {
63	        // Keep durable pending status. Settings provides reconnect/retry controls.
64	      } finally {
65	        running = false;
66	      }
67	    };
68	    const unsubscribe = client.onUpdate(
69	      deskStatusRef,
70	      {},
71	      () => {
72	        void sync();
73	      },
74	      () => {},
75	    );
76	    const timer = setInterval(() => {
77	      void sync();
78	    }, 60_000);
79	    const wake = () => {
80	      void sync();
81	    };
82	    window.addEventListener("online", wake);
83	    window.addEventListener(PUBLIC_DESK_SYNC_EVENT, wake);
84	    void sync();
85	    cleanup(() => {
86	      disposed = true;
87	      unsubscribe();
88	      clearInterval(timer);
89	      window.removeEventListener("online", wake);
90	      window.removeEventListener(PUBLIC_DESK_SYNC_EVENT, wake);
91	    });
92	  });
93	  return null;
94	});
