84	async function listLocalEvents(range: UsageRange): Promise<EventPage> {
85	  const events: UsageEvent[] = [];
86	  let cursor: string | undefined;
87	  let pages = 0;
88	  do {
89	    const page = await usageLedger.listUsageEvents({
90	      from: range.from,
91	      to: range.to,
92	      cursor,
93	    });
94	    events.push(...page.events);
95	    cursor = page.cursor;
96	    pages += 1;
97	  } while (cursor && pages < MAX_LOCAL_PAGES);
98	  return { events, truncated: Boolean(cursor) };
99	}
