32	async function countUsageRows(range: UsageRange): Promise<number> {
33	  let rows = 0;
34	  let cursor: string | undefined;
35	  do {
36	    const page = await usageLedger.listUsageEvents({
37	      from: range.from,
38	      to: range.to,
39	      cursor,
40	    });
41	    rows += page.events.length;
42	    cursor = page.cursor;
43	  } while (cursor);
44	  return rows;
45	}
