96	export const PublicDeskSettings = component$(() => {
97	  const auth = useAuth();
98	  const convex = useConvexClient();
99	  const state = useSignal<PublicDeskStatus | null>(null);
100	  const busy = useSignal(false);
101	  const error = useSignal("");
102	  // eslint-disable-next-line qwik/no-use-visible-task
103	  useVisibleTask$(({ track, cleanup }) => {
104	    const identity = track(() =>
105	      hasAuthenticatedConvexIdentity(auth.value) ? auth.value.user?.id : null,
106	    );
107	    const client = track(() => convex.value);
108	    state.value = null;
109	    if (!identity || !client) return;
110	    cleanup(
111	      client.onUpdate(
112	        deskStatusRef,
113	        {},
114	        (value) => {
115	          state.value = value;
116	        },
117	        () => {
118	          error.value =
119	            "Public desk settings could not load. Try again after reconnecting.";
120	        },
121	      ),
122	    );
123	  });
124	  const toggle = $(async (enabled: boolean) => {
125	    if (!convex.value || busy.value) return;
126	    busy.value = true;
127	    error.value = "";
