64	            accountId,
65	            uploader: createConvexUsageUploader(client),
66	          });
67	          if (!disposed) announceUsageSync(result);
68	        } catch {
69	          // Usage telemetry is an enhancement and must never interrupt writing.
70	          if (!disposed) {
71	            announceUsageSync({
72	              status: "partial",
73	              uploaded: 0,
74	              batches: 0,
75	            });
76	          }
77	        } finally {
78	          running = false;
79	        }
80	      };
