1	/**
2	 * GitHub-style "days writing" contribution heatmap. Renders the last ~371
3	 * days as week-columns of 7 day-squares, colored by activity count.
4	 */
5	
6	import { component$, type QRL } from "@qwik.dev/core";
7	
8	export interface ActivityDay {
9	  day: string; // "YYYY-MM-DD"
10	  count: number;
11	}
12	
13	const DAY_MS = 24 * 60 * 60 * 1000;
14	const WEEKS = 53;
15	
16	export function levelFor(count: number): 0 | 1 | 2 | 3 | 4 {
17	  if (count <= 0) return 0;
18	  if (count === 1) return 1;
19	  if (count <= 3) return 2;
20	  if (count <= 6) return 3;
21	  return 4;
22	}
23	
24	/**
25	 * A ramp from the paper rule up to full accent. Mixed rather than fixed so
26	 * the heatmap re-inks itself with the active theme instead of staying a strip
27	 * of warm orange on a cool or dark page.
28	 */
29	const LEVEL_COLORS = [
30	  "var(--color-paper-3)",
31	  "color-mix(in srgb, var(--color-vermilion) 22%, var(--color-paper-3))",
32	  "color-mix(in srgb, var(--color-vermilion) 48%, var(--color-paper-3))",
33	  "color-mix(in srgb, var(--color-vermilion) 74%, var(--color-paper-3))",
34	  "var(--color-vermilion)",
35	];
36	
37	export interface HeatmapCell {
38	  day: string;
39	  count: number;
40	}
41	
42	export function buildHeatmapWeeks(
43	  days: readonly ActivityDay[],
44	  now = Date.now(),
45	): HeatmapCell[][] {
46	  const byDay = new Map(days.map((day) => [day.day, day.count]));
47	  const today = new Date(now);
48	  today.setUTCHours(0, 0, 0, 0);
49	  const totalDays = WEEKS * 7;
50	  const endDow = today.getUTCDay();
51	  const start = new Date(
52	    today.getTime() - (totalDays - 1 - (6 - endDow)) * DAY_MS,
53	  );
54	  const weeks: HeatmapCell[][] = [];
55	  let cursor = new Date(start);
56	  for (let week = 0; week < WEEKS; week += 1) {
57	    const column: HeatmapCell[] = [];
58	    for (let day = 0; day < 7; day += 1) {
59	      const key = cursor.toISOString().slice(0, 10);
60	      column.push({
61	        day: key,
62	        count: cursor.getTime() > today.getTime() ? -1 : (byDay.get(key) ?? 0),
63	      });
64	      cursor = new Date(cursor.getTime() + DAY_MS);
65	    }
66	    weeks.push(column);
67	  }
68	  return weeks;
69	}
