77	    const client = convex.value;
78	    if (!client || busy.value) return;
79	    message.value = "";
80	    try {
81	      await client.mutation(api.accountExport.requestExport, {});
82	      awaiting.value = true;
83	    } catch {
84	      message.value = "The export could not be started. Try again.";
85	    }
86	  });
87	
88	  const current = latest.value;
89	  const running = current?.status === "running" || awaiting.value;
90	
91	  return (
92	    <div class="border-t border-[var(--color-ink)] pt-3">
93	      <h3 class="font-display text-sm font-semibold">Export everything</h3>
94	      <p class="mt-1 max-w-2xl text-xs text-[var(--color-ink-light)]">
95	        A zip of your manuscripts and their version history, briefs, personas,
96	        notes, comments, citations, published pieces, profile, settings, usage
97	        history, and Not Organic achievements. API keys and token secrets are
98	        never included.
99	      </p>
100	      <div class="mt-3 flex flex-wrap items-center gap-3">
101	        <button
102	          type="button"
103	          class="btn-paper"
104	          disabled={running || busy.value}
105	          onClick$={start}
106	        >
