108	        </button>
109	        {current?.status === "ready" && current.url && !running && (
110	          <button
111	            type="button"
112	            class="text-xs underline disabled:opacity-50"
113	            disabled={busy.value}
114	            onClick$={() => download(current.url!)}
115	          >
116	            Download the {new Date(current.createdAt).toLocaleString()} export
117	            {current.bytes ? ` (${formatBytes(current.bytes)})` : ""}
118	          </button>
119	        )}
120	      </div>
121	      {current?.status === "ready" && !running && (
122	        <p class="mt-2 text-xs text-[var(--color-ink-muted)]">
123	          Kept until {new Date(current.expiresAt).toLocaleString()}, then
124	          deleted.
125	        </p>
126	      )}
127	      {message.value && (
128	        <p class="mt-2 text-sm" role="status">
129	          {message.value}
130	        </p>
131	      )}
132	    </div>
133	  );
134	});
