708	/* ── Drop caret and gap cursor ────────────────────────────
709	   Where a dragged selection will land, and where the caret sits between two
710	   block nodes. Both extensions ship enabled via StarterKit but neither draws
711	   anything useful on its own: prosemirror-gapcursor has no styles at all
712	   without its stylesheet, and the drop caret defaults to a 1px hairline in the
713	   body text colour. Vermilion matches the editorial marks elsewhere in the
714	   manuscript, so the insertion point reads as an instruction rather than
715	   as part of the prose. */
716	.twyne-editor .twyne-dropcursor {
717	  background-color: var(--color-vermilion);
718	  border-radius: 1px;
719	  box-shadow: 0 0 0 1px
720	    color-mix(in srgb, var(--color-vermilion) 25%, transparent);
721	}
722	
723	.twyne-editor .ProseMirror-gapcursor {
724	  display: none;
725	  pointer-events: none;
726	  position: absolute;
727	}
728	
729	.twyne-editor .ProseMirror-gapcursor::after {
730	  content: "";
731	  display: block;
732	  position: absolute;
733	  top: -2px;
734	  width: 1.25rem;
735	  border-top: 2px solid var(--color-vermilion);
736	  animation: twyne-gapcursor-blink 1.1s steps(2, start) infinite;
737	}
